window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[190]={"id":"190","numero":190,"titre":"Fièvre prolongée","objectifs":[{"id":"190-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’une fièvre prolongée \"classique\"","contenu":"<p>La <span class=\"kw-def\">fièvre prolongée \"classique\"</span> — chez un sujet <strong>sans <span class=\"kw-def\">terrain</span> particulier</strong> — se définit par la réunion de <strong>trois critères</strong> obl<span class=\"kw-chiffre\">iga</span>toires.</p>\n      <ul>\n        <li><strong>Hauteur de la <span class=\"kw-clinique\">fièvre</span></strong> — <span class=\"kw-clinique\">T°</span> <span class=\"kw-chiffre\">≥ 38,3 °C</span> constatée <strong>à plusieurs reprises</strong>, au repos et à distance des repas. Voie axillaire ou buccale en ajoutant <span class=\"kw-chiffre\">+ 0,5 °C</span> à la valeur axillaire.</li>\n        <li><strong>Durée</strong> — <span class=\"kw-clinique\">évolution</span> depuis <span class=\"kw-chiffre\">≥ 3 semaines</span>.</li>\n        <li><strong>Absence de cause</strong> — aucun diagnostic malgré des invest<span class=\"kw-chiffre\">iga</span>tions appropriées (<strong>pas de liste pré-établie</strong> d'examens), constatée soit après <span class=\"kw-chiffre\">3 consultations</span>, soit durant <span class=\"kw-chiffre\">3 jours d'hospitalisation</span>.</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> La définition est <strong>adaptée à la situation clinique</strong> : une <span class=\"kw-clinique\">T°</span> à <span class=\"kw-chiffre\">38 °C</span> avec un <span class=\"kw-def\">syndrome inflammatoire</span> persistant relève de la même prise en charge qu'une <span class=\"kw-clinique\">fièvre</span> prolongée.</div>","frequence":3},{"id":"190-2","rang":"A","rubrique":"Étiologies","titre":"Connaître les trois principales catégories de causes de fièvres prolongées","contenu":"<p><span class=\"kw-clinique\">Les</span> causes de <span class=\"kw-clinique\">fièvre</span> prolongée se répartissent en <strong>trois grandes catégories</strong>, hiérarchisées par fréquence, auxquelles s'ajoute un groupe hétérogène « divers ».</p>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Fréquence</th><th>Chefs de file</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Infections</span></td><td><span class=\"kw-chiffre\">~ 40 %</span></td><td><span class=\"kw-etio\">tuberculose</span> ; <span class=\"kw-etio\">endocardite infectieuse</span> ; <span class=\"kw-etio\">primo-infections virales</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Causes néoplasiques</span></td><td><span class=\"kw-chiffre\">~ 20-30 %</span></td><td><span class=\"kw-etio\">lymphomes</span> ; <span class=\"kw-etio\">cancers solides</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Causes inflammatoires</span></td><td><span class=\"kw-chiffre\">~ 10 %</span></td><td><span class=\"kw-etio\">lupus systémique</span> ; <span class=\"kw-etio\">artérite à cellules géantes</span> ; <span class=\"kw-etio\">MICI</span></td></tr>\n          <tr><td>Divers</td><td>—</td><td><span class=\"kw-etio\">fièvre médicamenteuse</span> ; <span class=\"kw-etio\">maladie thrombo-embolique</span> ; <span class=\"kw-etio\">hyperthyroïdie</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Piège classique.</strong> Aucune cause n'est retrouvée dans <span class=\"kw-alerte\">plus de 30 % des cas</span> : il s'agit alors d'une <span class=\"kw-def\">fièvre prolongée inexpliquée</span>, dont le <strong><span class=\"kw-def\">pronostic</span> est généralement bon</strong> avec guérison spontanée sans <span class=\"kw-def\">diagnostic étiologique</span>.</div>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Le poids relatif de chaque catégorie dépend de plusieurs paramètres : la <strong>région géographique</strong> (<span class=\"kw-clinique\">les</span> causes infectieuses dominent dans les pays en développement, les causes néoplasiques et inflammatoires ailleurs), le <strong>mode de recrutement</strong> des patients, et l'<strong>âge</strong> (l'<span class=\"kw-etio\">artérite à cellules géantes</span> ne s'envisage qu'après <span class=\"kw-chiffre\">50 ans</span>).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 159 — <span class=\"kw-def\">Tuberculose</span> Enfant / Adulte · 194 — <span class=\"kw-def\">Lupus</span> - SAPL · 311 — Tumeur rénale</em></p>","frequence":1},{"id":"190-3","rang":"A","rubrique":"Étiologies","titre":"Connaître les principaux signes cliniques dans l’enquête étiologique d’une fièvre prolongée","contenu":"<p>Devant une <span class=\"kw-clinique\">fièvre</span> prolongée, l'<strong>interrogatoire</strong> et l'<strong>examen clinique</strong> sont <strong>complets et répétés</strong> à chaque consultation : la cause peut n'apparaître que secondairement.</p>\n      <p><strong>Interrogatoire</strong> — éléments à rechercher systématiquement :</p>\n      <table >\n        <thead><tr><th>Élément recherché</th><th>Orientation</th></tr></thead>\n        <tbody>\n          <tr><td>Consommation d'<strong><span class=\"kw-etio\">alcool</span></strong> et de <strong><span class=\"kw-etio\">tabac</span></strong></td><td>Augmentent le risque de <span class=\"kw-etio\">cancer</span></td></tr>\n          <tr><td><span class=\"kw-def\">Contact</span> avec des <strong>animaux</strong> ou des <strong>insectes</strong></td><td><span class=\"kw-etio\">zoonoses</span> ; maladies à transmission vectorielle</td></tr>\n          <tr><td><strong>Voyages</strong> récents</td><td><span class=\"kw-etio\">paludisme</span> ; <span class=\"kw-etio\">dengue</span> ; autres infections d'importation</td></tr>\n          <tr><td><strong>Profession</strong> et <strong>loisirs</strong></td><td>Expositions environnementales spécifiques</td></tr>\n          <tr><td><strong>Contage tuberculeux</strong>, y compris ancien</td><td><span class=\"kw-etio\">tuberculose</span></td></tr>\n          <tr><td><strong>Rapports sexuels</strong> à risque</td><td><span class=\"kw-etio\">VIH</span> ; autres <span class=\"kw-clinique\">IST</span></td></tr>\n          <tr><td><strong>Prises de médicaments</strong></td><td><span class=\"kw-etio\">fièvre médicamenteuse</span> — molécule parfois introduite plusieurs mois avant</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Examen clinique</strong> — complet et répété, il comporte notamment un <span class=\"kw-clinique\">examen gynécologique</span> chez la femme et un <span class=\"kw-clinique\">examen de la prostate et des organes génitaux</span> chez l'homme.</p>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Interrogatoire et examen clinique sont à <strong>répéter</strong> à chaque consultation : leur caractère initialement normal n'élimine rien, et un signe d'orientation peut émerger au fil de l'<span class=\"kw-clinique\">évolution</span>.</div>","frequence":0},{"id":"190-4","rang":"A","rubrique":"Étiologies","titre":"Citer les principales infections responsables de fièvre prolongée","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-etio\">infections</span> représentent <span class=\"kw-chiffre\">~ 40 %</span> des fièvres prolongées — la première catégorie étiologique. Distinguer les causes fréquentes (à évoquer en premier) des causes rares.</p>\n      <table >\n        <thead><tr><th>Rang</th><th>Infections responsables</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Fréquentes</strong></td><td>\n            <strong><span class=\"kw-etio\">Tuberculose</span> :</strong> surtout dans sa forme <span class=\"kw-etio\">extra-pulmonaire</span><br>\n            <strong><span class=\"kw-etio\">Endocardite infectieuse</span> :</strong> souvent à <span class=\"kw-etio\">hémocultures négatives</span><br>\n            <strong>Primo-infections virales :</strong> <span class=\"kw-etio\">EBV</span> ; <span class=\"kw-etio\">CMV</span><br>\n            <strong>Infections d'importation :</strong> <span class=\"kw-etio\">paludisme</span> ; <span class=\"kw-etio\">dengue</span>\n          </td></tr>\n          <tr><td><strong>Rares</strong></td><td>\n            <strong>Bactériennes :</strong> <span class=\"kw-etio\">bartonellose</span> ; <span class=\"kw-etio\">brucellose</span> ; <span class=\"kw-etio\">fièvre typhoïde</span> ; <span class=\"kw-etio\">rickettsiose</span> ; <span class=\"kw-etio\">leptospirose</span> ; <span class=\"kw-etio\">maladie de Whipple</span> ; <span class=\"kw-etio\">infections à mycobactéries</span><br>\n            <strong>Foyers profonds :</strong> <span class=\"kw-etio\">abcès profond</span> ; foyers dentaires, sinusiens, digestifs ; <span class=\"kw-etio\">infection urinaire</span> ; <span class=\"kw-etio\">infection ostéo-articulaire</span><br>\n            <strong>Virales :</strong> <span class=\"kw-etio\">VIH</span> ; <span class=\"kw-etio\">hépatites virales A, B, E</span><br>\n            <strong>Parasitaires :</strong> <span class=\"kw-etio\">toxoplasmose</span> ; <span class=\"kw-etio\">leishmaniose viscérale</span><br>\n            <strong>Fongiques (surtout chez l'immunodéprimé) :</strong> <span class=\"kw-etio\">candidoses systémiques</span> ; <span class=\"kw-etio\">cryptococcose</span> ; <span class=\"kw-etio\">histoplasmose</span> ; <span class=\"kw-etio\">aspergillose invasive</span>\n          </td></tr>\n        </tbody>\n      </table>\n      <p><strong>Focus — maladie de Whipple.</strong> Infection systémique <strong>rare</strong> à <span class=\"kw-etio\">Tropheryma whipplei</span> (bacille à Gram positif difficilement cultivable, contamination environnementale probable). Touche surtout l'<strong>homme</strong> (sex-ratio <span class=\"kw-chiffre\">9 H / 1 F</span>), âge moyen au diagnostic <span class=\"kw-chiffre\">50 ans</span>. Triade : <span class=\"kw-clinique\">fièvre prolongée</span> souvent intermittente, <span class=\"kw-clinique\">signes digestifs</span> (<span class=\"kw-clinique\">douleurs abdominales</span>, <span class=\"kw-clinique\">diarrhée</span> par malabsorption avec <span class=\"kw-clinique\">amaigrissement</span> et dénutrition) et <span class=\"kw-clinique\">polyarthralgies</span> intermittentes pouvant précéder le diagnostic de plusieurs années.</p>\n      <p>Confirmation : <span class=\"kw-bio\">biopsie duodénale</span> avec coloration <span class=\"kw-bio\">PAS</span> (<span class=\"kw-ttt\">infiltration</span> macrophagique, atrophie villositaire partielle) et <span class=\"kw-bio\">PCR de T. whipplei</span> sur <span class=\"kw-clinique\">les</span> liquides biologiques. Traitement : <span class=\"kw-ttt\">antibiothérapie</span> au long cours (<span class=\"kw-chiffre\">≥ 1 an</span>, environ <span class=\"kw-chiffre\">18 mois</span>) — <span class=\"kw-ttt\">doxycycline</span> ou <span class=\"kw-ttt\">cotrimoxazole</span>.</p>\n      <div class=\"callout callout-info\"><strong>Piège classique.</strong> La maladie de Whipple donne une <span class=\"kw-clinique\">polyarthrite à facteur rhumatoïde négatif</span> : l'évoquer chez un homme d'âge moyen associant <span class=\"kw-clinique\">fièvre</span> prolongée, signes digestifs et <span class=\"kw-clinique\">arthralgies</span>. Des <span class=\"kw-alerte\">masses ganglionnaires hypodenses péritonéales et mésentériques</span> au <span class=\"kw-imagerie\">scanner</span> sont très évocatrices ; la maladie peut se compliquer d'une <span class=\"kw-etio\">amylose AA</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 152 — <span class=\"kw-def\">Endocardite</span> infectieuse · 159 — <span class=\"kw-def\">Tuberculose</span> Enfant / Adulte · 170 — <span class=\"kw-clinique\">Paludisme</span> · 217 — Syndrome mononucléosique · 169 — <span class=\"kw-etio\">VIH</span> · 173 — Zoonose · 162 — <span class=\"kw-clinique\">IST</span> · 165 — Oreillons</em></p>","frequence":1},{"id":"190-5","rang":"A","rubrique":"Étiologies","titre":"Citer les principales causes non infectieuses de fièvre prolongée","contenu":"<p><span class=\"kw-clinique\">Les</span> causes <strong>non infectieuses</strong> se répartissent en trois groupes : <span class=\"kw-etio\">néoplasiques</span>, <span class=\"kw-etio\">inflammatoires</span> et « divers ».</p>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Fréquentes</th><th>Rares</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-etio\">Néoplasiques</span><br><span class=\"kw-chiffre\">20-30 %</span></td>\n            <td><span class=\"kw-etio\">lymphomes hodgkiniens</span> ; <span class=\"kw-etio\">lymphomes non hodgkiniens</span> ; <span class=\"kw-etio\">maladie de Waldenström</span> ; <span class=\"kw-etio\">cancer solide</span> (rein notamment)</td>\n            <td><span class=\"kw-etio\">myélodysplasie</span> ; <span class=\"kw-etio\">mésothéliome</span> ; <span class=\"kw-etio\">myélome multiple</span> ; <span class=\"kw-etio\">leucémies aiguës</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Inflammatoires</span><br><span class=\"kw-chiffre\">10 %</span></td>\n            <td><span class=\"kw-etio\">lupus systémique</span> ; <span class=\"kw-etio\">artérite à cellules géantes</span> et <span class=\"kw-etio\">PPR</span> ; <span class=\"kw-etio\">MICI</span></td>\n            <td><span class=\"kw-etio\">vascularites des petits vaisseaux</span> ; <span class=\"kw-etio\">périartérite noueuse</span> ; <span class=\"kw-etio\">maladie de Still de l'adulte</span> ; <span class=\"kw-etio\">polyarthrite rhumatoïde</span> ; <span class=\"kw-etio\">arthropathies microcristallines</span> (goutte, chondrocalcinose)</td>\n          </tr>\n          <tr>\n            <td>Divers</td>\n            <td><span class=\"kw-etio\">fièvre médicamenteuse</span> ; <span class=\"kw-etio\">maladie thrombo-embolique</span> ; <span class=\"kw-etio\">hyperthyroïdie</span></td>\n            <td><span class=\"kw-etio\">thyroïdite de De Quervain</span> ; <span class=\"kw-etio\">syndromes auto-inflammatoires</span> ; <span class=\"kw-etio\">syndrome d'activation lympho-histiocytaire</span> ; <span class=\"kw-etio\">hématome profond</span> ; <span class=\"kw-etio\">fièvre factice</span> ; <span class=\"kw-etio\">dysrégulation thermique autonome</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Focus — maladie de Still de l'adulte.</strong> Maladie <span class=\"kw-etio\">inflammatoire</span> du sujet de <span class=\"kw-chiffre\">&lt; 40 ans</span>, posée en <strong>diagnostic d'exclusion</strong> (après avoir éliminé <span class=\"kw-clinique\">les</span> autres maladies inflammatoires du sujet jeune). <span class=\"kw-clinique\">Fièvre hectique</span> très élevée (<span class=\"kw-chiffre\">40-41 °C</span>), à prédominance <strong>vespérale</strong> ; <span class=\"kw-clinique\">éruption cutanée saumonée non prurigineuse</span> ; <span class=\"kw-clinique\">arthralgies ou arthrites</span> ; <span class=\"kw-clinique\">pharyngite</span>. Biologie : <span class=\"kw-def\">syndrome inflammatoire</span> marqué avec hyperleucocytose à PNN, cytolyse hépatique, <span class=\"kw-bio\">hyperferritinémie</span> avec <strong>baisse de la fraction glycosylée</strong> de la <span class=\"kw-bio\">ferritine</span>.</p>\n      <p><strong>Focus — <span class=\"kw-clinique\">fièvre</span> méditerranéenne familiale (maladie périodique).</strong> <span class=\"kw-def\">Syndrome auto-inflammatoire</span> <span class=\"kw-etio\">héréditaire</span> monogénique le plus fréquent, à transmission <strong>récessive</strong>, touchant <span class=\"kw-clinique\">les</span> populations du <strong>pourtour méditerranéen</strong>. Début <span class=\"kw-chiffre\">&lt; 20 ans</span> dans <span class=\"kw-chiffre\">85 %</span> des cas. <span class=\"kw-clinique\">Fièvre intermittente</span> d'environ <span class=\"kw-chiffre\">36 h</span>, accompagnée de <span class=\"kw-clinique\">douleurs abdominales</span> intenses, <span class=\"kw-clinique\">arthralgies</span>, <span class=\"kw-clinique\">signes cutanés</span> et <span class=\"kw-clinique\">sérites</span>. Confirmation : analyse <span class=\"kw-etio\">génétique</span> — mutation du gène <span class=\"kw-bio\">MEFV</span> (codant la marénostrine). Traitement : <span class=\"kw-ttt\">colchicine</span>.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 194 — <span class=\"kw-def\">Lupus</span> - SAPL · 195 — Artérite à cellules géantes · 196 — <span class=\"kw-def\">Polyarthrite rhumatoïde</span> · 193 — <span class=\"kw-def\">Vascularite</span> systémique · 211 — <span class=\"kw-clinique\">Sarcoïdose</span> · 311 — Tumeur rénale · 241 — Goitre - <span class=\"kw-clinique\">nodule</span> - cancer thyroïdien</em></p>","frequence":1},{"id":"190-6","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître l’indication des examens d’imagerie devant une fièvre prolongée","contenu":"<p>L'imagerie fait partie du <strong>bilan paraclinique de <span class=\"kw-chiffre\">première intention</span></strong> de toute <span class=\"kw-clinique\">fièvre</span> prolongée. <span class=\"kw-clinique\">Les</span> examens sont <strong>hiérarchisés</strong> selon le minimum requis, la pratique courante et les points d'appel cliniques.</p>\n      <table >\n        <thead><tr><th>Niveau</th><th>Examens</th><th>Indication</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Au minimum</strong></td><td><span class=\"kw-imagerie\">radiographie thoracique</span> ; <span class=\"kw-imagerie\">échographie abdomino-pelvienne</span></td><td>Socle imagerie de toute <span class=\"kw-clinique\">fièvre</span> prolongée</td></tr>\n          <tr><td><strong>En pratique</strong></td><td><span class=\"kw-imagerie\">TDM thoraco-abdomino-pelvienne</span> avec injection</td><td>Le plus souvent prescrite, à la place des deux examens précédents</td></tr>\n          <tr><td><strong>Orientés</strong></td><td><span class=\"kw-imagerie\">TDM des sinus</span> ; <span class=\"kw-imagerie\">panoramique dentaire</span> ; <span class=\"kw-imagerie\">mammographie</span> ; <span class=\"kw-imagerie\">échographie cardiaque</span></td><td>Selon le contexte et <span class=\"kw-clinique\">les</span> points d'appel cliniques</td></tr>\n          <tr><td><strong>2ᵉ intention</strong></td><td><span class=\"kw-imagerie\">TEP-TDM au 18FDG</span></td><td>En cas d'<strong>absence d'orientation diagnostique</strong> après le bilan de <span class=\"kw-chiffre\">première ligne</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> La <span class=\"kw-imagerie\">TEP-TDM au 18FDG</span> n'est <strong>jamais</strong> un examen de <span class=\"kw-chiffre\">première intention</span> : elle se discute uniquement lorsque le bilan initial reste négatif et sans orientation.</div>","frequence":0},{"id":"190-7","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître la démarche diagnostique et la stratégie de hiérarchisation des examens complémentaires","contenu":"<p>La démarche diagnostique d'une <span class=\"kw-clinique\">fièvre</span> prolongée est <strong>hiérarchisée</strong> : un <strong>bilan de <span class=\"kw-chiffre\">première intention</span> systématique</strong>, puis un bilan de <span class=\"kw-chiffre\">deuxième intention</span> <strong>orienté</strong> par <span class=\"kw-clinique\">les</span> premiers résultats. Aucune liste d'examens n'est imposée par la définition, mais le bilan paraclinique initial — très tombé aux annales — est à connaître par cœur.</p>\n      <p><strong>Bilan paraclinique de <span class=\"kw-chiffre\">première intention</span></strong> :</p>\n      <table >\n        <thead><tr><th>Volet</th><th>Examens</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">Biologie</span></td><td>\n            <strong>Bilan standard :</strong> <span class=\"kw-bio\">NFS</span> ; <span class=\"kw-bio\">CRP</span> ; <span class=\"kw-bio\">ionogramme</span> ; <span class=\"kw-bio\">créatinine</span> ; <span class=\"kw-bio\">bilan hépatique</span> ; <span class=\"kw-bio\">bilan d'hémostase</span><br>\n            <strong>Orientés :</strong> <span class=\"kw-bio\">électrophorèse des protéines sériques</span> ; <span class=\"kw-bio\">calcémie</span> ; <span class=\"kw-bio\">ferritine</span> ; <span class=\"kw-bio\">TSHus</span> ; <span class=\"kw-bio\">LDH</span> ; <span class=\"kw-bio\">créatine kinase</span><br>\n            <strong>Immunologie :</strong> <span class=\"kw-bio\">anticorps anti-nucléaires</span> ; <span class=\"kw-bio\">facteur rhumatoïde</span> ; <span class=\"kw-bio\">ANCA</span>\n          </td></tr>\n          <tr><td><span class=\"kw-bio\">Microbiologie</span></td><td>\n            <strong><span class=\"kw-bio\">Hémocultures</span> × 3 :</strong> <span class=\"kw-alerte\">avant toute antibiothérapie</span><br>\n            <strong>Autres prélèvements :</strong> <span class=\"kw-bio\">ECBU</span> ; <span class=\"kw-bio\">IDR à la tuberculine</span><br>\n            <strong><span class=\"kw-bio\">Sérologies</span> :</strong> <span class=\"kw-bio\">EBV</span> ; <span class=\"kw-bio\">CMV</span> ; <span class=\"kw-bio\">VIH</span> ± <span class=\"kw-bio\">toxoplasmose</span>\n          </td></tr>\n          <tr><td><span class=\"kw-imagerie\">Imagerie</span></td><td>\n            <strong>Minimum :</strong> <span class=\"kw-imagerie\">radiographie thoracique</span> ; <span class=\"kw-imagerie\">échographie abdomino-pelvienne</span><br>\n            <strong>En pratique :</strong> <span class=\"kw-imagerie\">TDM thoraco-abdomino-pelvienne</span> injectée<br>\n            <strong>Orientés :</strong> <span class=\"kw-imagerie\">TDM des sinus</span> ; <span class=\"kw-imagerie\">panoramique dentaire</span> ; <span class=\"kw-imagerie\">mammographie</span> ; <span class=\"kw-imagerie\">échographie cardiaque</span>\n          </td></tr>\n        </tbody>\n      </table>\n      <p><strong>Conduite à tenir si le bilan de <span class=\"kw-chiffre\">première intention</span> reste négatif</strong> — quatre étapes :</p>\n      <ul>\n        <li><strong>Bilan de <span class=\"kw-chiffre\">deuxième intention</span></strong> guidé par le contexte, la clinique et <span class=\"kw-clinique\">les</span> premiers résultats d'examens.</li>\n        <li><span class=\"kw-imagerie\">TEP-TDM au 18FDG</span> en cas d'<strong>absence d'orientation diagnostique</strong>.</li>\n        <li>En l'absence de diagnostic final, le <strong><span class=\"kw-def\">pronostic</span> d'une <span class=\"kw-clinique\">fièvre</span> prolongée reste généralement bon</strong>.</li>\n        <li>Un <span class=\"kw-alerte\">traitement d'épreuve</span> n'est discuté que dans des <strong>cas exceptionnels</strong> où le <span class=\"kw-alerte\">pronostic vital</span> est en cause.</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> Toujours <strong>évoquer une forme atypique d'une maladie fréquente avant d'évoquer une maladie rare</strong>. Penser aussi systématiquement à la <span class=\"kw-etio\">fièvre médicamenteuse</span> : la liste des molécules en cause est large et le traitement peut avoir été introduit plusieurs mois avant la <span class=\"kw-clinique\">fièvre</span>.</div>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Urgence</span>.</strong> Le <span class=\"kw-alerte\">traitement d'épreuve</span> (<span class=\"kw-ttt\">corticothérapie</span>, <span class=\"kw-ttt\">traitement anti-tuberculeux</span> chez le sujet à risque…) est réservé aux situations <strong>exceptionnelles</strong> où le <span class=\"kw-alerte\">pronostic vital est en cause</span>, une fois la démarche diagnostique menée à son terme sans diagnostic formel.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 191 — <span class=\"kw-clinique\">Fièvre</span> chez l'immunodéprimé</em></p>","frequence":7}],"astuces":[],"strategie":{"principes":"<p><em>Stratégie de prise en charge à compléter — non disponible dans la source GitHub pour cet item.</em></p>"},"liensGlobaux":[{"href":"https://fr.wikipedia.org/wiki/Syndrome_de_M%C3%BCnchhausen","label":"Wikipedia — Syndrome de münchhausen"}],"cards":[{"i":"545a91f1ba34","n":190,"o":"190-1","u":"Définition","t":"Connaître la définition d’une fièvre prolongée \"classique\"","q":"Quel troisième critère, au-delà de la hauteur et de la durée, est obligatoire pour définir une fièvre prolongée \"classique\" ?","a":"<p>Le troisième critère est l'<strong>absence de diagnostic étiologique</strong> malgré des investigations appropriées. Cette absence de cause doit être constatée soit après <strong>3 consultations</strong>, soit durant <strong>3 jours d'hospitalisation</strong>.</p>"},{"i":"628999323e39","n":190,"o":"190-1","u":"Définition","t":"Connaître la définition d’une fièvre prolongée \"classique\"","q":"Quelle est la durée minimale requise pour parler de fièvre prolongée \"classique\" ?","a":"<p>La durée minimale requise est une évolution de la fièvre depuis <strong>au moins 3 semaines</strong> (≥ 3 semaines).</p>"},{"i":"92cbc83d5f7e","n":190,"o":"190-1","u":"Définition","t":"Connaître la définition d’une fièvre prolongée \"classique\"","q":"Comment définit-on la hauteur de la fièvre dans le cadre d'une fièvre prolongée \"classique\" ?","a":"<p>La hauteur de la fièvre est définie par une température <strong>supérieure ou égale à 38,3 °C</strong>, constatée à plusieurs reprises, au repos et à distance des repas. La prise de température doit être effectuée par voie axillaire ou buccale, en ajoutant 0,5 °C à la valeur axillaire si celle-ci est utilisée.</p>"},{"i":"0eada8bcadea","n":190,"o":"190-2","u":"Étiologies","t":"Connaître les trois principales catégories de causes de fièvres prolongées","q":"Quels sont les chefs de files à retenir pour les causes néoplasiques et inflammatoires de fièvre prolongée ?","a":"<ul><li>Pour les <strong>causes néoplasiques</strong> : les <strong>lymphomes</strong> et les <strong>cancers solides</strong>.</li><li>Pour les <strong>causes inflammatoires</strong> : le <strong>lupus systémique</strong>, l'<strong>artérite à cellules géantes</strong> et les <strong>MICI</strong> (Maladies Inflammatoires Chroniques de l'Intestin).</li></ul>"},{"i":"9d209d911083","n":190,"o":"190-2","u":"Étiologies","t":"Connaître les trois principales catégories de causes de fièvres prolongées","q":"Dans la catégorie des causes infectieuses de fièvre prolongée, quels sont les chefs de files à retenir ?","a":"<p>Dans la catégorie des causes infectieuses de fièvre prolongée, les chefs de files à retenir sont :</p><ul><li>La <strong>tuberculose</strong></li><li>L'<strong>endocardite infectieuse</strong></li><li>Les <strong>primo-infections virales</strong></li></ul>"},{"i":"cfc7e772cdf2","n":190,"o":"190-2","u":"Étiologies","t":"Connaître les trois principales catégories de causes de fièvres prolongées","q":"Selon le collège de l'EDN, quelles sont les trois principales catégories d'étiologies de la fièvre prolongée, classées par fréquence ?","a":"<p>Les trois principales catégories d'étiologies de la fièvre prolongée, classées par fréquence, sont :</p><ul><li>Les <strong>infections</strong> (~ 40 %)</li><li>Les <strong>causes néoplasiques</strong> (~ 20-30 %)</li><li>Les <strong>causes inflammatoires</strong> (~ 10 %)</li></ul>"},{"i":"eb84483890f5","n":190,"o":"190-2","u":"Étiologies","t":"Connaître les trois principales catégories de causes de fièvres prolongées","q":"Quel est le piège classique concernant les étiologies de la fièvre prolongée ?","a":"<p>Le piège classique est qu'<strong>aucune cause n'est retrouvée dans plus de 30 % des cas</strong>. On parle alors de <strong>fièvre prolongée inexpliquée</strong> dont le pronostic est généralement bon avec guérison spontanée sans diagnostic étiologique.</p>"},{"i":"04d7672dfbd1","n":190,"o":"190-3","u":"Étiologies","t":"Connaître les principaux signes cliniques dans l’enquête étiologique d’une fièvre prolongée","q":"Quelles spécificités l'examen clinique doit-il comporter dans le cadre d'une fièvre prolongée selon le sexe du patient ?","a":"<p>Dans le cadre d'une fièvre prolongée, l'examen clinique doit être complet et répété, incluant spécifiquement :</p><ul><li>Un <strong>examen gynécologique</strong> chez la femme.</li><li>Un <strong>examen de la prostate et des organes génitaux</strong> chez l'homme.</li></ul>"},{"i":"4c9cecf916dc","n":190,"o":"190-3","u":"Étiologies","t":"Connaître les principaux signes cliniques dans l’enquête étiologique d’une fièvre prolongée","q":"Quelle doit être la particularité de l'interrogatoire et de l'examen clinique dans l'enquête étiologique d'une fièvre prolongée ?","a":"<p>L'interrogatoire et l'examen clinique doivent être <strong>complets et répétés à chaque consultation</strong>. Leur normalité initiale n'élimine pas une cause, et un signe d'orientation peut apparaître secondairement au cours de l'évolution.</p>"},{"i":"db44cd70384f","n":190,"o":"190-3","u":"Étiologies","t":"Connaître les principaux signes cliniques dans l’enquête étiologique d’une fièvre prolongée","q":"Quels sont les principaux éléments de l'interrogatoire à rechercher systématiquement face à une fièvre prolongée ?","a":"<p>Face à une fièvre prolongée, l'interrogatoire doit rechercher les éléments suivants :</p><ul><li>La consommation d'<strong>alcool</strong> et de <strong>tabac</strong> (recherche de facteur de risque de cancer).</li><li>Les <strong>contacts avec des animaux ou des insectes</strong> (orientation vers des zoonoses ou maladies vectorielles).</li><li>Les <strong>voyages récents</strong> (orientation vers paludisme, dengue, infections d'importation).</li><li>La <strong>profession et les loisirs</strong> (expositions environnementales spécifiques).</li><li>Les <strong>contages tuberculeux</strong>, même anciens.</li><li>Les <strong>rapports sexuels à risque</strong> (orientation vers VIH, IST).</li><li>Les <strong>prises de médicaments</strong> (recherche de fièvre médicamenteuse, même si la molécule a été introduite plusieurs mois auparavant).</li></ul>"},{"i":"359eed5812d3","n":190,"o":"190-4","u":"Étiologies","t":"Citer les principales infections responsables de fièvre prolongée","q":"Quelles sont les causes infectieuses bactériennes rares à ne pas méconnaître dans l'étiologie d'une fièvre prolongée ?","a":"<p>Parmi les causes infectieuses bactériennes rares de fièvre prolongée, il faut rechercher :</p><ul><li>La <strong>bartonellose</strong>.</li><li>La <strong>brucellose</strong>.</li><li>La <strong>fièvre typhoïde</strong>.</li><li>Les <strong>rickettsioses</strong>.</li><li>La <strong>leptospirose</strong>.</li><li>La <strong>maladie de Whipple</strong>.</li><li>Les <strong>infections à mycobactéries</strong> (autres que la tuberculose classique).</li></ul>"},{"i":"4264ce186450","n":190,"o":"190-4","u":"Étiologies","t":"Citer les principales infections responsables de fièvre prolongée","q":"Quelles sont les étiologies infectieuses non bactériennes rares de fièvre prolongée, en dehors des primo-infections virales fréquentes ?","a":"<p>En dehors des primo-infections virales fréquentes, les étiologies infectieuses non bactériennes rares de fièvre prolongée comprennent :</p><ul><li>Les <strong>foyers profonds</strong> (abcès, infections dentaires/sinusiennes/digestives/urinaires/ostéo-articulaires).</li><li>Les <strong>infections virales</strong> (VIH, hépatites virales A, B, E).</li><li>Les <strong>infections parasitaires</strong> (toxoplasmose, leishmaniose viscérale).</li><li>Les <strong>infections fongiques</strong> (candidose systémique, cryptococcose, histoplasmose, aspergillose invasive), surtout chez l'immunodéprimé.</li></ul>"},{"i":"8ad998ac6aea","n":190,"o":"190-4","u":"Étiologies","t":"Citer les principales infections responsables de fièvre prolongée","q":"Quelle est la triade classique de la maladie de Whipple et comment se réalise son diagnostic de certitude ?","a":"<p>La triade clinique de la maladie de Whipple est :</p><ul><li>Une <strong>fièvre prolongée</strong>, souvent intermittente.</li><li>Des <strong>signes digestifs</strong> (douleurs abdominales, diarrhée par malabsorption avec amaigrissement et dénutrition).</li><li>Des <strong>polyarthralgies intermittentes</strong>, pouvant précéder le diagnostic de plusieurs années.</li></ul><p>Le diagnostic de certitude repose sur une <strong>biopsie duodénale</strong> montrant une infiltration macrophagique avec coloration PAS positive et une atrophie villositaire partielle, associée à une <strong>PCR de <em>Tropheryma whipplei</em></strong> sur les liquides biologiques.</p>"},{"i":"a22af12e3248","n":190,"o":"190-4","u":"Étiologies","t":"Citer les principales infections responsables de fièvre prolongée","q":"Quelles sont les causes infectieuses fréquentes à évoquer en priorité devant une fièvre prolongée, selon le référentiel de l'EDN ?","a":"<p>Devant une fièvre prolongée, les causes infectieuses fréquentes à évoquer en priorité sont les suivantes :</p><ul><li>La <strong>tuberculose</strong> (surtout dans sa forme extra-pulmonaire).</li><li>L'<strong>endocardite infectieuse</strong> (souvent à hémocultures négatives).</li><li>Les <strong>primo-infections virales</strong> (EBV, CMV).</li><li>Les <strong>infections d'importation</strong> (paludisme, dengue).</li></ul>"},{"i":"4be277de3352","n":190,"o":"190-5","u":"Étiologies","t":"Citer les principales causes non infectieuses de fièvre prolongée","q":"Quelles sont les causes néoplasiques fréquentes de fièvre prolongée ?","a":"<p>Les causes néoplasiques fréquentes de fièvre prolongée sont :</p><ul><li>Les <strong>lymphomes hodgkiniens</strong></li><li>Les <strong>lymphomes non hodgkiniens</strong></li><li>La <strong>maladie de Waldenström</strong></li><li>Les <strong>cancers solides</strong> (notamment le cancer du rein)</li></ul>"},{"i":"82bcb737b21a","n":190,"o":"190-5","u":"Étiologies","t":"Citer les principales causes non infectieuses de fièvre prolongée","q":"Quels sont les éléments biologiques évocateurs de la maladie de Still de l'adulte en cas de fièvre prolongée ?","a":"<p>Les éléments biologiques évocateurs de la maladie de Still de l'adulte sont :</p><ul><li>Un <strong>syndrome inflammatoire marqué</strong></li><li>Une <strong>hyperleucocytose à PNN</strong></li><li>Une <strong>cytolyse hépatique</strong></li><li>Une <strong>hyperferritinémie avec une baisse de la fraction glycosylée de la ferritine</strong></li></ul>"},{"i":"9fde4ebd66f3","n":190,"o":"190-5","u":"Étiologies","t":"Citer les principales causes non infectieuses de fièvre prolongée","q":"Quelles sont les caractéristiques principales de la fièvre méditerranéenne familiale, cause de fièvre prolongée ?","a":"<p>La fièvre méditerranéenne familiale est :</p><ul><li>Le syndrome <strong>auto-inflammatoire héréditaire monogénique le plus fréquent</strong>.</li><li>Elle est de transmission <strong>récessive</strong> et touche les populations du pourtour méditerranéen.</li><li>Elle se manifeste par une <strong>fièvre intermittente d'environ 36 heures</strong>, accompagnée de <strong>douleurs abdominales intenses</strong>, d'arthralgies, de signes cutanés et de sérites.</li><li>Le diagnostic est confirmé par l'<strong>analyse génétique</strong> (mutation du <strong>gène MEFV</strong>).</li><li>Le traitement repose sur la <strong>colchicine</strong>.</li></ul>"},{"i":"b548fae21145","n":190,"o":"190-5","u":"Étiologies","t":"Citer les principales causes non infectieuses de fièvre prolongée","q":"Quelles sont les causes non infectieuses diverses de fièvre prolongée ?","a":"<p>Les causes non infectieuses diverses de fièvre prolongée sont :</p><ul><li>La <strong>fièvre médicamenteuse</strong></li><li>La <strong>maladie thrombo-embolique</strong></li><li>L'<strong>hyperthyroïdie</strong></li><li>La thyroïdite de De Quervain</li><li>Les syndromes auto-inflammatoires (ex: <strong>fièvre méditerranéenne familiale</strong>)</li><li>Le syndrome d'activation lympho-histiocytaire</li><li>L'hématome profond</li><li>La fièvre factice</li><li>La dysrégulation thermique autonome</li></ul>"},{"i":"b83398340212","n":190,"o":"190-5","u":"Étiologies","t":"Citer les principales causes non infectieuses de fièvre prolongée","q":"Quelles sont les caractéristiques cliniques de la maladie de Still de l'adulte, cause de fièvre prolongée ?","a":"<p>La maladie de Still de l'adulte se caractérise par :</p><ul><li>Une <strong>fièvre hectique très élevée</strong> (<strong>40-41 °C</strong>), à prédominance vespérale.</li><li>Une <strong>éruption cutanée saumonée non prurigineuse</strong>.</li><li>Des arthralgies ou des arthrites.</li><li>Une pharyngite.</li></ul>"},{"i":"d8d453a613a3","n":190,"o":"190-5","u":"Étiologies","t":"Citer les principales causes non infectieuses de fièvre prolongée","q":"Quelles sont les causes inflammatoires fréquentes de fièvre prolongée ?","a":"<p>Les causes inflammatoires fréquentes de fièvre prolongée sont :</p><ul><li>Le <strong>lupus systémique</strong></li><li>L'<strong>artérite à cellules géantes</strong> et la <strong>pseudopolyarthrite rhizomélique (PPR)</strong></li><li>Les <strong>maladies inflammatoires chroniques de l'intestin (MICI)</strong></li></ul>"}]};